                <Grid item xs={12}>
                  <Typography variant="subtitle1" gutterBottom>Message Events Configuration</Typography>
                  <Grid container spacing={2}>
                    <Grid item xs={12} md={6}>
                      <TextField
                        fullWidth
                        label="Average Events per Day"
                        type="number"
                        value={networkLoadConfig.messages.events_per_day}
                        onChange={(e) => handleNetworkConfigChange('messages', 'events_per_day', e.target.value)}
                        size="small"
                      />
                    </Grid>
                    <Grid item xs={12} md={6}>
                      <TextField
                        fullWidth
                        label="Average Message Size (KB)"
                        type="number"
                        value={networkLoadConfig.messages.message_size_kb}
                        onChange={(e) => handleNetworkConfigChange('messages', 'message_size_kb', e.target.value)}
                        size="small"
                      />
                    </Grid>
                  </Grid>
                </Grid>
              </Grid>

              <Box sx={{ mt: 3, display: 'flex', justifyContent: 'flex-end' }}>
                <Button
                  variant="contained"
                  onClick={() => setNetworkLoadModalOpen(false)}
                >
                  Save Configuration
                </Button>
              </Box>
            </Box>
          </Modal>

          <Modal
            open={cloudConfigModalOpen}
            onClose={() => setCloudConfigModalOpen(false)}
          >
            <Box sx={modalStyle}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                <Typography variant="h6">Cloud Provider & Region Configuration</Typography>
                <IconButton onClick={() => setCloudConfigModalOpen(false)} size="small">
                  <CloseIcon />
                </IconButton>
              </Box>

              <Grid container spacing={3}>
                <Grid item xs={12}>
                  <FormControl fullWidth>
                    <InputLabel>Cloud Provider</InputLabel>
                    <Select
                      value={formData.cloud_provider}
                      onChange={handleProviderChange}
                      label="Cloud Provider"
                    >
                      {Object.entries(cloudProviders).map(([key, provider]) => (
                        <MenuItem key={key} value={key}>
                          {provider.name}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12}>
                  <FormControl fullWidth>
                    <InputLabel>Region</InputLabel>
                    <Select
                      value={formData.region}
                      onChange={handleRegionChange}
                      label="Region"
                    >
                      {cloudProviders[formData.cloud_provider].regions.map((region) => (
                        <MenuItem key={region.id} value={region.id}>
                          {region.name} ({region.id}) - {region.id === 'us-east-1' ? '1.0x' :
                            region.id === 'us-west-2' ? '1.05x' :
                            region.id === 'eu-west-1' ? '1.12x' :
                            region.id === 'ap-southeast-1' ? '1.15x' : '1.0x'} base price
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12}>
                  <Typography variant="body2" color="text.secondary">
                    Current Region: {cloudProviders[formData.cloud_provider].regions.find(r => r.id === formData.region)?.name}
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    Price Multiplier: {formData.region === 'us-east-1' ? '1.0x' :
                      formData.region === 'us-west-2' ? '1.05x' :
                      formData.region === 'eu-west-1' ? '1.12x' :
                      formData.region === 'ap-southeast-1' ? '1.15x' : '1.0x'} base price
                  </Typography>
                </Grid>
              </Grid>

              <Box sx={{ mt: 3, display: 'flex', justifyContent: 'flex-end', gap: 2 }}>
                <Button
                  variant="outlined"
                  onClick={() => setCloudConfigModalOpen(false)}
                >
                  Close
                </Button>
              </Box>
            </Box>
          </Modal>

          <Box sx={{ mt: 3 }}>
            <Button
              variant="contained"
              color="primary"
              size="large"
              onClick={calculateCosts}
            >
              Calculate Costs
            </Button>
          </Box>
        </Box>

        {costBreakdown && (
          <Box sx={{ mt: 4 }}>
            <Typography variant="h5" gutterBottom>Cost Breakdown ({costPeriod.charAt(0).toUpperCase() + costPeriod.slice(1)})</Typography>
            <Grid container spacing={3}>
              <Grid item xs={12} md={6}>
                <Paper 
                  elevation={2} 
                  sx={{ 
                    p: 2, 
                    cursor: 'pointer',
                    '&:hover': { bgcolor: 'action.hover' }
                  }}
                  onClick={() => handleShowDetails('pxgrid', costBreakdown?.breakdown?.pxgrid_cost)}
                >
                  <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                    <Typography variant="subtitle1">Network Data Load Costs</Typography>
                    <InfoIcon color="action" fontSize="small" />
                  </Box>
                  <Typography variant="h6">{formatCurrency(costBreakdown?.breakdown?.pxgrid_cost)}</Typography>
                  <Typography variant="caption" color="text.secondary">
                    Base cost: {formatCurrency(costBreakdown?.breakdown?.pxgrid_cost / (
                      formData.region === 'us-east-1' ? 1.0 :
                      formData.region === 'us-west-2' ? 1.05 :
                      formData.region === 'eu-west-1' ? 1.12 :
                      formData.region === 'ap-southeast-1' ? 1.15 : 1.0
                    ))}
                  </Typography>
                </Paper>
              </Grid>
              <Grid item xs={12} md={6}>
                <Paper 
                  elevation={2} 
                  sx={{ 
                    p: 2, 
                    cursor: 'pointer',
                    '&:hover': { bgcolor: 'action.hover' }
                  }}
                  onClick={() => handleShowDetails('storage', costBreakdown?.breakdown?.storage)}
                >
                  <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                    <Typography variant="subtitle1">Storage Costs</Typography>
                    <InfoIcon color="action" fontSize="small" />
                  </Box>
                  <Typography variant="h6">{formatCurrency(
                    (costBreakdown?.breakdown?.storage?.dynamodb_cost || 0) +
                    (costBreakdown?.breakdown?.storage?.s3_cost || 0)
                  )}</Typography>
                  <Typography variant="body2">DynamoDB: {formatCurrency(costBreakdown?.breakdown?.storage?.dynamodb_cost)}</Typography>
                  <Typography variant="body2">S3: {formatCurrency(costBreakdown?.breakdown?.storage?.s3_cost)}</Typography>
                </Paper>
              </Grid>
              <Grid item xs={12} md={6}>
                <Paper 
                  elevation={2} 
                  sx={{ 
                    p: 2, 
                    cursor: 'pointer',
                    '&:hover': { bgcolor: 'action.hover' }
                  }}
                  onClick={() => handleShowDetails('container', costBreakdown?.breakdown?.container_cost)}
                >
                  <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                    <Typography variant="subtitle1">Container Costs</Typography>
                    <InfoIcon color="action" fontSize="small" />
                  </Box>
                  <Typography variant="h6">{formatCurrency(costBreakdown?.breakdown?.container_cost)}</Typography>
                  <Typography variant="caption" color="text.secondary">
                    Base cost: {formatCurrency(costBreakdown?.breakdown?.container_cost / (
                      formData.region === 'us-east-1' ? 1.0 :
                      formData.region === 'us-west-2' ? 1.05 :
                      formData.region === 'eu-west-1' ? 1.12 :
                      formData.region === 'ap-southeast-1' ? 1.15 : 1.0
                    ))}
                  </Typography>
                </Paper>
              </Grid>
              <Grid item xs={12} md={6}>
                <Paper 
                  elevation={2} 
                  sx={{ 
                    p: 2, 
                    cursor: 'pointer',
                    '&:hover': { bgcolor: 'action.hover' }
                  }}
                  onClick={() => handleShowDetails('network', costBreakdown?.breakdown?.network)}
                >
                  <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                    <Typography variant="subtitle1">Network Costs</Typography>
                    <InfoIcon color="action" fontSize="small" />
                  </Box>
                  <Typography variant="h6">{formatCurrency(
                    (costBreakdown?.breakdown?.network?.throughput_cost || 0) +
                    (costBreakdown?.breakdown?.network?.msk_cost || 0)
                  )}</Typography>
                  <Typography variant="body2">Throughput: {formatCurrency(costBreakdown?.breakdown?.network?.throughput_cost)}</Typography>
                  <Typography variant="body2">MSK: {formatCurrency(costBreakdown?.breakdown?.network?.msk_cost)}</Typography>
                </Paper>
              </Grid>
              <Grid item xs={12}>
                <Paper elevation={3} sx={{ p: 2, bgcolor: 'primary.light', color: 'primary.contrastText' }}>
                  <Typography variant="h6">Total Monthly Cost: {formatCurrency(costBreakdown?.total_cost)}</Typography>
                  <Typography variant="subtitle1">Cost per Tenant: {formatCurrency(costBreakdown?.monthly_cost_per_tenant)}</Typography>
                  <Typography variant="caption">
                    Base cost (before region multiplier): {formatCurrency(costBreakdown?.total_cost / (
                      formData.region === 'us-east-1' ? 1.0 :
                      formData.region === 'us-west-2' ? 1.05 :
                      formData.region === 'eu-west-1' ? 1.12 :
                      formData.region === 'ap-southeast-1' ? 1.15 : 1.0
                    ))}
                  </Typography>
                </Paper>
              </Grid>
            </Grid>

            <CostDetailModal />
          </Box>
        )}

        <Snackbar
          open={notification.open}
          autoHideDuration={6000}
          onClose={handleCloseNotification}
        >
          <Alert onClose={handleCloseNotification} severity={notification.severity}>
            {notification.message}
          </Alert>
        </Snackbar>
      </Paper>
    </Container>
  );
}

export default CostCalculator;
